import itertools
import json

def solve_puzzle():
    # Input variables
    houses = [1, 2, 3]  # left to right
    Names = ["Arnold", "Peter", "Eric"]
    Heights = ["short", "average", "very short"]

    solutions = []

    # Helper to get position of a value in assignment dict
    def pos_of_value(assign_dict, value):
        for h, v in assign_dict.items():
            if v == value:
                return h
        return None

    # Enumerate all possible height assignments
    for heights_perm in itertools.permutations(Heights):
        height_at_house = {house: heights_perm[i] for i, house in enumerate(houses)}

        # Clue 2: The person who is short is in the first house.
        if height_at_house[1] != "short":
            continue

        # Clue 3: There is one house between the person who is short and the person who is very short.
        pos_short = pos_of_value(height_at_house, "short")
        pos_very_short = pos_of_value(height_at_house, "very short")
        if abs(pos_short - pos_very_short) != 2:
            continue

        # Enumerate all possible name assignments
        for names_perm in itertools.permutations(Names):
            name_at_house = {house: names_perm[i] for i, house in enumerate(houses)}

            # Clue 1: Peter is somewhere to the right of Eric.
            pos_peter = pos_of_value(name_at_house, "Peter")
            pos_eric = pos_of_value(name_at_house, "Eric")
            if not (pos_peter > pos_eric):
                continue

            # Clue 4: Arnold and the person who is very short are next to each other.
            pos_arnold = pos_of_value(name_at_house, "Arnold")
            if abs(pos_arnold - pos_very_short) != 1:
                continue

            # All constraints satisfied; record solution
            solution_rows = []
            for h in houses:
                solution_rows.append([str(h), name_at_house[h], height_at_house[h]])
            solutions.append(solution_rows)

    # Assume unique solution for this puzzle; take the first if multiple
    final_rows = solutions[0] if solutions else []

    output = {
        "solution": {
            "header": ["House", "Name", "Height"],
            "rows": final_rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, indent=2, ensure_ascii=False))
